<script setup lang="ts">
import{ref,watch,onBeforeUnmount,onMounted}from'vue';import{v1}from'../api';
const props=defineProps<{runId:string}>(),emit=defineEmits<{(e:'close'):void;(e:'locate',payload:{id:string;runId:string}):void}>();
const query=ref(''),input=ref<HTMLInputElement>(),matches=ref<Array<{id:string;runId:string;text:string;authorType:string}>>([]),index=ref(0),busy=ref(false),error=ref(''),truncated=ref(false);let timer:ReturnType<typeof setTimeout>,controller:AbortController|undefined;
watch([query,()=>props.runId],()=>{clearTimeout(timer);controller?.abort();matches.value=[];if(!query.value.trim())return;timer=setTimeout(load,160);});
async function load(){const c=new AbortController();controller=c;busy.value=true;error.value='';try{const data=await v1<{matches:typeof matches.value;truncated:boolean}>(`/api/v1/runs/${props.runId}/find?q=${encodeURIComponent(query.value)}`,{signal:c.signal});if(c.signal.aborted)return;matches.value=data.matches;truncated.value=data.truncated;index.value=0;}catch(e){if(!c.signal.aborted)error.value=String(e);}finally{if(!c.signal.aborted)busy.value=false;}}
function go(delta:number){if(!matches.value.length)return;index.value=(index.value+delta+matches.value.length)%matches.value.length;emit('locate',matches.value[index.value]!);}
onMounted(()=>input.value?.focus());onBeforeUnmount(()=>{clearTimeout(timer);controller?.abort();});
</script>
<template><section class="conversation-find" aria-label="会话查找" @keydown.esc.stop="emit('close')"><div class="find-bar"><input ref="input" v-model="query" placeholder="查找当前会话…" maxlength="200" aria-label="查找当前会话" @keydown.enter.prevent="go($event.shiftKey?-1:1)"><small>{{busy?'查找中…':matches.length?`${index+1}/${matches.length}${truncated?'+':''}`:'0条'}}</small><button class="icon-btn" aria-label="上一个结果" @click="go(-1)">↑</button><button class="icon-btn" aria-label="下一个结果" @click="go(1)">↓</button><button class="icon-btn" aria-label="关闭查找" @click="emit('close')">×</button></div><p v-if="error" role="alert">{{error}}</p><div v-if="matches.length" class="find-results"><button v-for="(m,i) in matches" :key="m.id" :class="{selected:i===index}" @click="index=i;emit('locate',m)"><small>{{m.authorType==='user'?'你':m.authorType==='research'?'研究':'Agent'}}</small>{{m.text}}</button></div></section></template>
<style scoped>.conversation-find{width:var(--conversation-content-width);margin:0 auto 8px;padding:8px;border:1px solid var(--border);border-radius:10px;background:var(--bg-panel);flex:none}.find-bar{display:flex;align-items:center;gap:6px}.find-bar input{flex:1;min-width:0;border:0;background:transparent;color:var(--fg);font:inherit;outline:none}.find-bar small{font-size:11px;white-space:nowrap;color:var(--fg-subtle)}.find-results{max-height:130px;overflow:auto;display:grid;gap:2px;margin-top:6px}.find-results button{text-align:left;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--fg);background:transparent;border:0;border-radius:6px;padding:6px;font:inherit;font-size:12px}.find-results button.selected,.find-results button:hover{background:var(--hover)}.find-results small{margin-right:10px;color:var(--fg-subtle)}[role=alert]{color:var(--danger);font-size:12px}</style>
